def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Check if the object has any fields to iterate over
    # This assumes the object represents a record with named fields
    try:
        # Try to get the field names or keys
        field_names = [f.name for f in self._fields] if hasattr(self, '_fields') else None
    except Exception:
        field_names = None

    if not keys:
        return list(self)

    result = []
    for key in keys:
        try:
            if field_names and isinstance(key, str):
                # It's a key name lookup
                if key in field_names:
                    result.append(self[key])
                else:
                    raise KeyError("Unknown key: {}".format(key))
            elif isinstance(key, int):
                # It's an index lookup
                result.append(self[key])
            elif isinstance(key, bytes):
                # Convert bytes to string and try as key name
                try:
                    key_str = key.decode('utf-8')
                    if field_names and key_str in field_names:
                        result.append(self[key_str])
                    else:
                        raise KeyError("Unknown key: {}".format(key))
                except UnicodeDecodeError:
                    # If it can't be decoded, maybe it's an index
                    if -len(self) <= key < len(self):
                        try:
                            result.append(self[key])
                        except TypeError:
                            pass
                    else:
                        raise KeyError("Invalid key: {}".format(key))
            else:
                raise TypeError("Key must be a string, integer, or bytes, got: {}".format(type(key)))
        except KeyError:
            raise  # Re-raise key errors
        except TypeError as e:
            raise TypeError("Invalid key type: {}".format(str(e)))
        except Exception as e:
            raise ValueError("Error accessing key {}: {}".format(key, str(e)))
    return result
