def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    try:
        base_cls = dict.__new__(type)
        base_cls.__name__ = name
        base_cls.__qualname__ = name

        # Dynamically set __init__
        field_names = list(fields.keys())

        def __init__(self, *args, **kwargs):
            if len(args) != len(field_names):
                raise TypeError(f"{name}() takes {len(field_names)} arguments, got {len(args)}")
            if kwargs:
                raise TypeError(f"{name}() got multiple values for argument or unexpected keyword argument: {list(kwargs.keys())[0]}")
            for fname, val in zip(field_names, args):
                self.__dict__[fname] = val

        setattr(base_cls, '__init__', __init__)

        # Define nested SRID if needed (not strictly required but provides context)
        for field_name, field_type in fields.items():
            if hasattr(field_type, 'srid') and field_type.srid in srid_map:
                srid_info = srid_map[field_type.srid]
                nested_name = f"{name}.{srid_info[1]}"
                nested_cls = type(nested_name, (tuple,), {})
                setattr(base_cls, nested_name, nested_cls)

        return base_cls

    except Exception as e:
        # Re-raise if something unexpected happens during creation
        raise e
