def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    # Strip any leading "v" or "V"
    if s and s[0] in ('v', 'V'):
        s = s[1:]

    # Split the version string by dots
    parts = s.split('.')

    result = []
    for part in parts:
        # Find the first non-digit character in the part
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break

        if num_str:
            result.append(int(num_str))
        else:
            # If no digit found, append 0
            result.append(0)

    return tuple(result)
