import threading

class MRUCache:
    def __init__(self, maxsize):
        self.maxsize = maxsize
        self.cache = {}
        self.order = []
        self.lock = threading.RLock()

    def __getitem__(self, key):
        with self.lock:
            if key in self.cache:
                return self.cache[key]
            raise KeyError(key)

    def __setitem__(self, key, value):
        with self.lock:
            if key in self.cache:
                # already cached, just update value
                self.cache[key] = value
            else:
                if len(self.cache) >= self.maxsize:
                    # evict oldest entry
                    oldest_key = self.order.pop(0)
                    del self.cache[oldest_key]
                self.cache[key] = value
                self.order.append(key)

    def __len__(self):
        with self.lock:
            return len(self.cache)

    def clear(self):
        with self.lock:
            self.cache.clear()
            self.order.clear()


def mru_cache(maxsize=128, typed=False):
    import functools

    def wrapper(func):
        cache = MRUCache(maxsize)
        cache_key_cols = func.__code__.co_argcount
        result_cache = {}
        cache_lock = threading.Lock()

        @functools.wraps(func)
        def wrapper_(*args, **kwargs):
            key = args
            if typed:
                value = kwargs
            else:
                value = None
            full_key = (args, frozenset(kwargs.items()), value)

            with cache_lock:
                try:
                    return cache[full_key]
                except KeyError:
                    pass

            result = func(*args, **kwargs)

            with cache_lock:
                cache[full_key] = result

            return result

        wrapper_.cache_info = lambda: {"size": len(cache), "maxsize": maxsize}
        wrapper_.cache_clear = cache.clear
        return wrapper_

    return wrapper
