def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        from dea.core.messages import FillRequest, Source
    except Exception:
        return False
    if seq is None:
        return False
    if isinstance(seq, FillRequest):
        return True
    if isinstance(seq, Source):
        return False
    if isinstance(seq, (list, tuple, set, frozenset)):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
            if isinstance(item, Source):
                return False
        return False
    if hasattr(seq, '__iter__'):
        for item in seq:
            if isinstance(item, FillRequest):
                return True
            if isinstance(item, Source):
                return False
        return False
    return False
