def difference(d1, d2, level=-1):
    result = {}

    for key in d1:
        if key not in d2:
            result[key] = d1[key]
        elif level == -1:
            # Infinite recursion: recurse if both values are dicts
            val1 = d1[key]
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                sub_diff = difference(val1, val2, level)
                if sub_diff:
                    result[key] = sub_diff
            else:
                if val1 != val2:
                    result[key] = val1
        else:
            # Finite recursion
            val1 = d1[key]
            val2 = d2[key]
            if isinstance(val1, dict) and isinstance(val2, dict):
                if level > 1:
                    sub_diff = difference(val1, val2, level - 1)
                    if sub_diff:
                        result[key] = sub_diff
                # When level == 1, we don't recurse; if values differ (including dicts), include val1
                if level == 1 and val1 != val2:
                    result[key] = val1
            else:
                if val1 != val2:
                    result[key] = val1

    return result

