def update_last_applied_manifest_list_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_dict_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (list): partial ``last_applied_manifest`` being
            updated
        observer_schema (list): partial ``observer_schema``
        response (list): partial response from the Kubernetes API.

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    if not isinstance(last_applied_manifest, list):
        return

    if not isinstance(observer_schema, list):
        return

    if len(last_applied_manifest) < len(observer_schema):
        # extend last_applied_manifest with None values to match the length of observer_schema
        last_applied_manifest.extend([None] * (len(observer_schema) - len(last_applied_manifest)))

    for i, (manifest_item, schema_item) in enumerate(zip(last_applied_manifest, observer_schema)):
        if manifest_item is not None and schema_item is not None:
            if isinstance(manifest_item, dict) and isinstance(schema_item, dict):
                update_last_applied_manifest_dict_from_resp(manifest_item, schema_item, response)
            elif isinstance(manifest_item, list) and isinstance(schema_item, list):
                update_last_applied_manifest_list_from_resp(manifest_item, schema_item, response)
            else:
                # for scalar values, initialize from response if not present
                if isinstance(response, list) and i < len(response) and response[i] is not None:
                    last_applied_manifest[i] = response[i]
        elif manifest_item is None and schema_item is not None:
            # initialize manifest_item from response if available
            if isinstance(response, list) and i < len(response) and response[i] is not None:
                last_applied_manifest[i] = response[i]
                if isinstance(schema_item, dict):
                    update_last_applied_manifest_dict_from_resp(last_applied_manifest[i], schema_item, response[i])
                elif isinstance(schema_item, list):
                    update_last_applied_manifest_list_from_resp(last_applied_manifest[i], schema_item, response[i])
