def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    for key, value in observer_schema.items():
        if key == None or key is None:
            continue
        if isinstance(value, dict):
            # Recursively handle nested dicts
            if key not in last_applied_manifest:
                last_applied_manifest[key] = {}
            # Check if the key exists in the response, and get its value. If it's missing, raise KeyError
            if key not in response:
                raise KeyError(f"Observed field {key} is not present in the Kubernetes response")
            response_value = response[key]
            if response_value is None:
                # If the response value is None, we might just keep the current dict, or set it to {}? Let's think.
                # The spec says "initialized their value in last_applied_manifest if they are not yet present"
                # But for dict, it recurses. If the response value is None, it means the field exists but is null.
                # It might be safer to treat None as an empty dict for the purpose of recursion,
                # or just set last_applied_manifest[key] to {}.
                # Let's see the context: if we haven't set it, it's initialized to {}. If it exists, we recurse.
                # If response_value is None, we can't recurse. So we should not touch the dict part.
                # Actually, let's look at the logic. It updates the dict if not present? No, it says "go through all observed fields, and initialized their value in last_applied_manifest if they are not yet present".
                # The docstring says "This function go through all observed fields, and initialized their value in last_applied_manifest if they are not yet present".
                # But it also takes response, so it must update from response.
                pass
            if isinstance(response_value, dict):
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], observer_schema[key], response_value
                )
            else:
                # Leaf node? Wait, if it's not a dict and not None, maybe it's a primitive or list?
                # The function name says "dict_from_resp", implying it's for dict-like structures.
                # Let's re-read the doc: "updates a partial last_applied_manifest from a partial Kubernetes response".
                # The `observer_schema` is a dict of key -> schema.
                # If the schema node is non-dict, it's a leaf. We should update the last_applied_manifest with the value from response.
                if key not in response:
                    raise KeyError(f"Observed field {key} is not present in the Kubernetes response")
                last_applied_manifest[key] = response[key]
        elif isinstance(value, list):
            # It's a list?
            if key not in last_applied_manifest:
                last_applied_manifest[key] = []
            # If the response has a list, we need to handle it.
            if key not in response:
                raise KeyError(f"Observed field {key} is not present in the Kubernetes response")
            # In the context of Kubernetes resources (like lists of objects), we should process each element.
            # However, a generic implementation might be tricky.
            # Let's check if the elements of the list are dicts, and recurse.
            response_value = response[key]
            if response_value is None:
                pass
            elif isinstance(response_value, list):
                for idx, item in enumerate(response_value):
                    if idx >= len(last_applied_manifest[key]):
                        last_applied_manifest[key].append({})
                    if isinstance(item, dict):
                        update_last_applied_manifest_dict_from_resp(
                            last_applied_manifest[key][idx], observer_schema[key][0] if observer_schema[key] else {}, item
                        )
                    else:
                        # primitive, just assign
                        last_applied_manifest[key][idx] = item
            else:
                # not a list, handle as primitive?
                last_applied_manifest[key] = response_value
        else:
            # Prvalue (primitive or leaf node)
            if key not in response:
                raise KeyError(f"Observed field {key} is not present in the Kubernetes response")
            last_applied_manifest[key] = response[key]
