		Convert the SQL query to use the out-style parameters instead of
		the in-style parameters.

		*sql* (:class:`str` or :class:`bytes`) is the SQL query.

		*params* (:class:`~collections.abc.Mapping` or :class:`~collections.abc.Sequence`)
		contains the set of in-style parameters. It maps each parameter
		(:class:`str` or :class:`int`) to value. If :attr:`.SQLParams.in_style`
		is a named parameter style. then *params* must be a :class:`~collections.abc.Mapping`.
		If :attr:`.SQLParams.in_style` is an ordinal parameter style, then
		*params* must be a :class:`~collections.abc.Sequence`.

		Returns a :class:`tuple` containing:

		-	The formatted SQL query (:class:`str` or :class:`bytes`).

		-	The set of converted out-style parameters (:class:`dict` or
			:class:`list`).
		"""
		if isinstance(sql, bytes):
			# Convert bytes to str for processing
			is_bytes = True
			try:
				sql_str = sql.decode('utf-8')
			except UnicodeDecodeError:
				# Fallback: use backslashreplace to avoid failure
				sql_str = sql.decode('utf-8', errors='backslashreplace')
			# Decode parameter values if they are bytes
			def _decode(v):
				if isinstance(v, bytes):
					try:
						return v.decode('utf-8')
					except UnicodeDecodeError:
						return v.decode('utf-8', errors='backslashreplace')
				return v
		else:
			is_bytes = False
			sql_str = sql
			_decode = lambda v: v

		if isinstance(self.in_style, str) and self.in_style in ('pyformat', 'qmark', 'named'):
			# Named or qmark formats
			pass
		else:
			# Treat as named by default if not recognized
			pass

		# Determine in_style
		in_style = getattr(self, 'in_style', 'pyformat')

		# Determine out_style
		out_style = getattr(self, 'out_style', 'pyformat')

		# Helper function for escaping in pyformat/named styles
		def _escape(s):
			# Simple escape: replace % with %% for pyformat
			return s.replace(b'\\', b'\\\\').replace(b'%', b'%%') if isinstance(s, bytes) else s.replace('\\', '\\\\').replace('%', '%%')

		if in_style == 'named':
			if not isinstance(params, dict):
				raise TypeError("params must be a dict for named in_style")
			# Convert to ordinal: replace :name or {name} with ?
			# We need to substitute and collect parameters in order.
			converted_params = []
			# Regex for :name
			import re
			pattern = re.compile(r':(\w+)')
			new_sql_str = []
			last_end = 0
			for match in pattern.finditer(sql_str):
				name = match.group(1)
				# Append literal part
				new_sql_str.append(sql_str[last_end:match.start()])
				# Append ?
				new_sql_str.append('?')
				last_end = match.end()
				if name not in params:
					raise ValueError(f"Missing parameter: {name}")
				converted_params.append(_decode(params[name]))
			new_sql_str.append(sql_str[last_end:])
			new_sql_str = ''.join(new_sql_str)

			# Now convert ordinal to out_style
			if out_style == 'qmark':
				final_sql_str = new_sql_str
			elif out_style == 'pyformat':
				# Replace ? with %s
				final_sql_str = new_sql_str.replace('?', '%s')
			elif out_style == 'numeric':
				# Replace ? with :1, :2, etc.
				# Count ? and replace sequentially
				count = 0
				def repl(a):
					nonlocal count
					count += 1
					return f':{count}'
				final_sql_str = re.sub(r'\?', repl, new_sql_str)
			else:
				final_sql_str = new_sql_str

			if not isinstance(converted_params, (list, tuple)):
				converted_params = list(converted_params)

			if is_bytes:
				try:
					final_sql = final_sql_str.encode('utf-8')
				except UnicodeEncodeError:
					final_sql = final_sql_str.encode('utf-8', errors='backslashreplace')
				# Re-encode param values
				def _encode(v):
					if isinstance(v, str):
						return v.encode('utf-8')
					return v
				if isinstance(converted_params, list):
					converted_params = [_encode(v) for v in converted_params]
			else:
				final_sql = final_sql_str

			return (final_sql, converted_params)

		elif in_style == 'qmark':
			if not isinstance(params, (list, tuple)):
				raise TypeError("params must be a sequence for qmark in_style")
			# Replace ? in sql with out_style placeholders
			if out_style == 'qmark':
				final_sql_str = sql_str
			elif out_style == 'pyformat':
				final_sql_str = sql_str.replace('?', '%s')
			elif out_style == 'numeric':
				count = 0
				def repl(a):
					nonlocal count
					count += 1
					return f':{count}'
				import re
				final_sql_str = re.sub(r'\?', repl, sql_str)
			else:
				final_sql_str = sql_str

			converted_params = list(params[:])
			# Decode/encode as needed
			if is_bytes:
				try:
					final_sql = final_sql_str.encode('utf-8')
				except UnicodeEncodeError:
					final_sql = final_sql_str.encode('utf-8', errors='backslashreplace')
				def _encode(v):
					if isinstance(v, str):
						return v.encode('utf-8')
					return v
				converted_params = [_encode(v) for v in converted_params]
			else:
				final_sql = final_sql_str

			return (final_sql, converted_params)

		elif in_style == 'pyformat':
			if not isinstance(params, (dict, list, tuple)):
				raise TypeError("params must be a mapping or sequence for pyformat in_style")
			# pyformat uses %(name)s or %s
			# Determine if named or positional
			# If params is dict, it's named. If list, positional.
			if isinstance(params, dict):
				# Named pyformat
				import re
				pattern = re.compile(r'%\((\w+)\)s')
				new_sql_str = []
				converted_params = []
				last_end = 0
				for match in pattern.finditer(sql_str):
					name = match.group(1)
					new_sql_str.append(sql_str[last_end:match.start()])
					new_sql_str.append('?')
					last_end = match.end()
					if name not in params:
						raise ValueError(f"Missing parameter: {name}")
					converted_params.append(_decode(params[name]))
				new_sql_str.append(sql_str[last_end:])
				new_sql_str = ''.join(new_sql_str)

				if out_style == 'qmark':
					final_sql_str = new_sql_str
				elif out_style == 'pyformat':
					final_sql_str = new_sql_str.replace('?', '%s')
				elif out_style == 'numeric':
					count = 0
					def repl(a):
						nonlocal count
						count += 1
						return f':{count}'
					final_sql_str = re.sub(r'\?', repl, new_sql_str)
				else:
					final_sql_str = new_sql_str
			else:
				# Positional pyformat: %s
				load = 0
				def repl(a):
					nonlocal load
					load += 1
					return '?'
				import re
				new_sql_str = re.sub(r'%s', repl, sql_str)
				converted_params = list(params[:])

				if out_style == 'qmark':
					final_sql_str = new_sql_str
				elif out_style == 'pyformat':
					final_sql_str = new_sql_str.replace('?', '%s')
				elif out_style == 'numeric':
					count = 0
					def repl2(a):
						nonlocal count
						count += 1
						return f':{count}'
					final_sql_str = re.sub(r'\?', repl2, new_sql_str)
				else:
					final_sql_str = new_sql_str

			if not isinstance(converted_params, (list, tuple)):
				converted_params = list(converted_params)

			if is_bytes:
				try:
					final_sql = final_sql_str.encode('utf-8')
				except UnicodeEncodeError:
					final_sql = final_sql_str.encode('utf-8', errors='backslashreplace')
				def _encode(v):
					if isinstance(v, str):
						return v.encode('utf-8')
					return v
				converted_params = [_encode(v) for v in converted_params]
			else:
				final_sql = final_sql_str

			return (final_sql, converted_params)

		else:
			# Fallback: assume qmark
			if not isinstance(params, (list, tuple)):
				raise TypeError("params must be a sequence for this in_style")
			final_sql_str = sql_str
			converted_params = list(params[:])
			if is_bytes:
				try:
					final_sql = final_sql_str.encode('utf-8')
				except UnicodeEncodeError:
					final_sql = final_sql_str.encode('utf-8', errors='backslashreplace')
				def _encode(v):
