def validate(self, inventory, extract_spec_version=False):
    # Handle invalid inventory
    if not isinstance(inventory, str):
        try:
            inventory = str(inventory)
        except Exception as e:
            raise ValueError(f"Unable to convert inventory to string: {e}")

    if not inventory.strip():
        raise ValueError("Inventory string is empty or contains only whitespace")

    # Extract specification version if requested
    spec_version = self.spec_version if hasattr(self, 'spec_version') else None
    if extract_spec_version:
        # Look for type value to determine spec version
        type_match = None
        # Try to find type field in the inventory
        # Common patterns: "type: <version>", "spec_version: <version>", or similar
        import re
        # Look for common type indicators
        type_patterns = [
            r'type\s*[:=]\s*(\d+)',
            r'spec_version\s*[:=]\s*(\d+)',
            r'spec-version\s*[:=]\s*(\d+)',
            r'specification\s+version\s*[:=]?\s*(\d+)',
            r'type\s*[:=]\s*v?(\d+)',
        ]
        for pattern in type_patterns:
            type_match = re.search(pattern, inventory, re.IGNORECASE)
            if type_match:
                break

        if type_match:
            try:
                spec_version = int(type_match.group(1))
            except (ValueError, IndexError):
                # If cannot parse, fall back to self.spec_version
                if hasattr(self, 'spec_version'):
                    spec_version = self.spec_version
                else:
                    raise ValueError("Could not determine valid specification version from inventory")

    # Additional validation: check that the inventory contains some expected content
    # Basic sanity check - the inventory should not be extremely short
    if len(inventory.strip()) < 1:
        raise ValueError("Inventory is invalid (empty after stripping)")

    # If spec_version was extracted or is available, you might want to do version-specific validation
    # For now, we just return the spec_version to indicate successful validation
    return spec_version

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    missing_digests = []
    unused_digests = []
    for file_id, digest_info in manifest_files.items():
        # Assume digest_info contains or can provide the required status
        if not digest_info.get('used', False):
            missing_digests.append(file_id)
        # If the manifest says a digest is required/expected but it's not in digests_used
        if file_id not in digests_used:
            missing_digests.append(file_id)
    for file_id in digests_used:
        if file_id not in manifest_files:
            unused_digests.append(file_id)
    # In the next block, raise an error if any issues found
    has_error = False
    error_msg = ""
    if missing_digests:
        error_msg += "Missing digests: " + ", ".join(missing_digests)
        has_error = True
    if unused_digests:
        if has_error:
            error_msg += "; "
        error_msg += "Unused digests: " + ", ".join(unused_digests)
        has_error = True
    if has_error:
        raise ValueError(error_msg)

