    def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("fixity must be a dictionary")

        # Check structure: fixity should contain 'files' key
        if 'files' not in fixity:
            raise ValueError("fixity block is missing 'files' key")

        files_block = fixity['files']
        if not isinstance(files_block, dict):
            raise ValueError("fixity['files'] must be a dictionary")

        for filename, file_data in files_block.items():
            # Check if the file is in the manifest
            if filename not in manifest_files:
                raise ValueError(f"File '{filename}' referenced in fixity but not found in manifest")

            # Validate each file's entry structure
            if not isinstance(file_data, dict):
                raise ValueError(f"fixity['files']['{filename}'] must be a dictionary")

            required_keys = {'digests'}
            if not required_keys.issubset(file_data.keys()):
                for key in required_keys - file_data.keys():
                    raise ValueError(f"fixity file '{filename}' is missing required key: '{key}'")

            # Validate digests structure
            digests = file_data['digests']
            if not isinstance(digests, dict):
                raise ValueError(f"fixity['files']['{filename}']['digests'] must be a dictionary")

            # Each digest should be a list of dicts with 'alg' and 'value'
            for digest_alg, digest_entries in digests.items():
                if not isinstance(digest_entries, list):
                    raise ValueError(f"fixity['files']['{filename}']['digests']['{digest_alg}'] must be a list")
                for entry in digest_entries:
                    if not isinstance(entry, dict):
                        raise ValueError("Each digest entry must be a dictionary")
                    if 'alg' not in entry or 'value' not in entry:
                        raise ValueError("Each digest entry must contain 'alg' and 'value' keys")
                    if not isinstance(entry['alg'], str) or not entry['alg']:
                        raise ValueError("Digest entry 'alg' must be a non-empty string")
                    if not isinstance(entry['value'], str) or not entry['value']:
                        raise ValueError("Digest entry 'value' must be a non-empty string")
