def _explore_zipfile(zip_path):
    import zipfile
    import xml.etree.ElementTree as ET
    import os

    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for member in zf.infolist():
                if not member.is_dir():
                    try:
                        with zf.open(member) as f:
                            data = f.read()
                            base_name = os.path.basename(member.filename).split('.')[0]
                            if data and member.filename.endswith('.xml'):
                                try:
                                    root = ET.fromstring(data)
                                    result.setdefault(base_name, []).append(root)
                                except ET.ParseError:
                                    result.setdefault(base_name, []).append(data.decode('utf-8', errors='ignore'))
                            else:
                                result.setdefault(base_name, []).append(data)
                    except Exception as e:
                        base_name = os.path.basename(member.filename).split('.')[0]
                        result.setdefault(base_name, []).append(f"Error: {str(e)}")
    except Exception as e:
        raise ValueError(f"Failed to explore zip file: {str(e)}")
    return result

