def pretty(self, indent=0, debug=False):
    cls = self.__class__.__name__
    prefix = ' ' * indent
    lines = [prefix + cls + '']
    for name, attr in vars(self).items():
        lines.append(prefix + '  ' + name + ': ' + type(attr).__name__)
    if debug:
        for name, attr in vars(self).items():
            lines.append(prefix + '  ' + name + ' = ' + repr(attr))
