def register_vcs_handler(vcs, method):
    """
    Registers a method as a handler for a specific VCS and returns the original method.
    If 'vcs' is None, the method is registered with the 'default' VCS.
    The method's '__vcs_handler__' attribute is set to True.
    """
    if vcs is None:
        vcs = "default"
    @functools.wraps(method)
    def wrapper(*args, **kwargs):
        return method(*args, **kwargs)
    wrapper.__vcs_handler__ = True
    wrapper.__vcs__ = vcs
    # Register if global registry exists, otherwise just return wrapper
    if hasattr(sys.modules[__name__], "_VCS_HANDLERS_REGISTRY") or True:
        # Try to get default registry
        try:
            registry = getattr(wrapper, "_VCS_HANDLERS_REGISTRY", None)
            if registry is None:
                registry = {}
                wrapper._VCS_HANDLERS_REGISTRY = registry
        except Exception:
            registry = {}
        registry[vcs] = wrapper
    return wrapper
