def deep_merge_nodes(nodes):
    from ruamel.yaml.nodes import MappingNode, ScalarNode

    if not nodes:
        return []

    # Group by key value (the string value of the ScalarNode key)
    key_map = {}
    key_order = []

    for key_node, value_node in nodes:
        # Use the value of the scalar key as our grouping key
        key_val = key_node.value if isinstance(key_node, ScalarNode) else key_node

        if key_val not in key_map:
            key_map[key_val] = {
                'key_node': key_node,
                'values': []  # list of value_nodes
            }
            key_order.append(key_val)
        else:
            key_map[key_val]['values'].append(value_node)

    result = []

    for key_val in key_order:
        entry = key_map[key_val]
        key_node = entry['key_node']
        values = entry['values']

        if len(values) == 1:
            result.append((key_node, values[0]))
        else:
            # Check if all values are MappingNodes
            all_mappings = all(isinstance(v, MappingNode) for v in values)
            if all_mappings:
                # Deep merge the mapping nodes
                merged = values[0].copy()
                for mapping_node in values[1:]:
                    _merge_mapping_into(merged, mapping_node)
                result.append((key_node, merged))
            else:
                # Last value wins
                result.append((key_node, values[-1]))

    return result


def _merge_mapping_into(target: MappingNode, source: MappingNode):
    """
    Merge source MappingNode into target MappingNode in-place.
    For duplicate keys: if both values are MappingNode, recursively merge; otherwise source wins.
    """
    from ruamel.yaml.nodes import MappingNode

    # Build a map of source keys
    source_key_map = {}
    source_key_order = []
    for key_node, value_node in source.value:
        key_val = key_node.value if hasattr(key_node, 'value') else key_node
        if key_val not in source_key_map:
            source_key_order.append(key_val)
            source_key_map[key_val] = (key_node, value_node)

    # Existing target keys
    target_key_map = {}
    target_key_order = []
    for key_node, value_node in target.value:
        key_val = key_node.value if hasattr(key_node, 'value') else key_node
        if key_val not in target_key_map:
            target_key_order.append(key_val)
            target_key_map[key_val] = (key_node, value_node)

    # Build the new merged value list
    new_value_list = []
    new_key_order = list(target_key_order)

    for key_val in new_key_order:
        if key_val in source_key_map and key_val in target_key_map:
            # Both have this key
            _, target_val = target_key_map[key_val]
            _, source_val = source_key_map[key_val]

            if isinstance(target_val, MappingNode) and isinstance(source_val, MappingNode):
                # Recursively merge
                _merge_mapping_into(target_val, source_val)
                # Keep the target key node and the updated target_val
                new_value_list.append((target_key_map[key_val][0], target_val))
            else:
                # Source wins
                new_value_list.append((source_key_map[key_val][0], source_val))
        elif key_val in source_key_map:
            # Only in source
            new_value_list.append(source_key_map[key_val])
        else:
            # Only in target
            new_value_list.append(target_key_map[key_val])

    # Replace target's value with the merged list
    target.value = new_value_list

