def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    # Collect flags from _actions
    if hasattr(parser, '_actions'):
        for action in parser._actions:
            if hasattr(action, 'option_strings'):
                for opt in action.option_strings:
                    flags.append(opt)
    # Also consider parent parsers (e.g. from add_argument)
    if hasattr(parser, '_parents'):
        for parent in parser._parents:
            if hasattr(parent, '_actions'):
                for action in parent._actions:
                    if hasattr(action, 'option_strings'):
                        for opt in action.option_strings:
                            if opt not in flags:
                                flags.append(opt)
    return ' '.join(flags)
