def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    try:
        iterable = iter(dicts)
    except TypeError:
        return result

    for d in iterable:
        if not isinstance(d, dict):
            continue
        for key, value in d.items():
            if key in result:
                # Attempt to add, if addition fails due to incompatible types, replace with the new value
                try:
                    result[key] += value
                except TypeError:
                    result[key] = value
            else:
                result[key] = value
    return result

