from typing import List

def string_to_int(string: str, alphabet: List[str]) -> int:
    # Validate inputs
    if not isinstance(string, str):
        raise TypeError("Input string must be a string")
    if not isinstance(alphabet, list):
        raise TypeError("Alphabet must be a list")
    if len(alphabet) < 2:
        raise ValueError("Alphabet must have at least 2 elements")
    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must contain single-character strings")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("Alphabet must contain unique characters")

    # Create a mapping from character to its index in the alphabet
    char_to_index = {char: idx for idx, char in enumerate(alphabet)}

    # If the string is empty, return 0
    if len(string) == 0:
        return 0

    # Convert the string to a number
    result = 0
    base = len(alphabet)

    for char in string:
        if char not in char_to_index:
            raise ValueError(f"Character {char!r} is not in the alphabet")
        result = result * base + char_to_index[char]

    return result
