def parse_frequency(frequency):
    if frequency is None:
        return None
    if frequency == "always":
        return None
    try:
        number_str, unit = frequency.split()
        number = int(number_str)
        if number < 0:
            raise ValueError("Frequency must be non-negative")
        unit = unit.lower()
        if unit == "second" or unit == "sec" or unit == "s":
            return datetime.timedelta(seconds=number)
        elif unit == "minute" or unit == "min" or unit == "m":
            return datetime.timedelta(minutes=number)
        elif unit == "hour" or unit == "hr" or unit == "h":
            return datetime.timedelta(hours=number)
        elif unit == "day" or unit == "d":
            return datetime.timedelta(days=number)
        elif unit == "week" or unit == "wk" or unit == "w":
            return datetime.timedelta(weeks=number)
        elif unit == "month" or unit == "mo" or unit == "mon":
            return None  # Monthly frequency not represented in timedelta, yield None
        elif unit == "year" or unit == "yr" or unit == "y":
            return None  # Yearly frequency not represented in timedelta, yield None
        else:
            raise ValueError("Unsupported frequency unit: {0}".format(unit))
    except (ValueError, TypeError, AttributeError):
        raise ValueError("Invalid frequency: {0}".format(frequency))

