def get_pattern(pattern, strip=True):
    if not isinstance(pattern, str):
        raise TypeError("Pattern must be a string")

    if strip:
        pattern = pattern.strip()

    # Escape any backslashes first to avoid double-escaping
    pattern = pattern.replace('\\', '\\\\')

    # Replace leading/trailing anchors
    # Note: this is a simplified approach; a full converter would handle more cases
    if pattern.startswith('^') and pattern.endswith('$'):
        pattern = '^' + escape_characters(pattern[1:-1]) + '$'
    elif pattern.startswith('^'):
        pattern = '^' + escape_characters(pattern[1:])
    elif pattern.endswith('$'):
        pattern = escape_characters(pattern[:-1]) + '$'
    else:
        pattern = escape_characters(pattern)

    # Re-unescape escaped backslashes that we added
    pattern = pattern.replace('\\\\', '\\')

    return pattern

def escape_characters(s):
    # Escape all regex special characters
    special_chars = r'.*+?^${}[]|\()'
    escaped = []
    for c in s:
        if c in special_chars:
            escaped.append('\{}'.format(c))
        else:
            escaped.append(c)
    return ''.join(escaped)

