import os

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if isinstance(commands, list):
        cmd = " ".join(commands)
    else:
        cmd = commands

    # Use the command as the first element
    if isinstance(cmd, list):
        full_cmd = cmd
    else:
        # Parse the command line into tokens
        import shlex
        full_cmd = shlex.split(cmd)

    # Extend with the provided arguments
    full_cmd.extend(args)

    if verbose:
        print("Running command:", " ".join(full_cmd))
        if cwd:
            print("in directory:", cwd)

    # Prepare environment
    env_full = None
    if env is not None:
        env_full = dict(os.environ)
        env_full.update(env)
    elif cwd is not None:
        # If cwd is provided but env is None, we can still use default env
        env_full = None
        # Actually, if cwd is provided and env is not, we may want to set PATH appropriately,
        # but the standard behavior is to just use the default environment.
        # Let's leave it as None to use the parent's environment.

    try:
        # Execute the command
        proc = subprocess.Popen(
            full_cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE if not hide_stderr else None,
            env=env_full
        )
        stdout, stderr = proc.communicate()

        if verbose:
            if stdout:
                for line in stdout.splitlines():
                    print("  " + line.decode('utf-8', errors='replace') if isinstance(line, bytes) else line)
            if not hide_stderr and stderr:
                for line in stderr.splitlines():
                    print("  " + line.decode('utf-8', errors='replace') if isinstance(line, bytes) else line, file=sys.stderr)

        # Check the return code
        if proc.returncode != 0:
            raise subprocess.CalledProcessError(proc.returncode, full_cmd, stdout=stdout, stderr=stderr)

        return stdout

    except subprocess.CalledProcessError as e:
        if verbose and e.stderr:
            print("Command failed with error:", file=sys.stderr)
            for line in e.stderr.splitlines():
                print(line.decode('utf-8', errors='replace') if isinstance(line, bytes) else line, file=sys.stderr)
        raise

    except Exception as e:
        if verbose:
            print("Error executing command:", str(e), file=sys.stderr)
        raise
