import logging
import os
import json
import yaml

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    logger = logging.getLogger(__name__)
    configs = {}
    errors = []
    overrides = overrides if overrides is not None else {}

    for filename in config_filenames:
        try:
            # Determine file format based on extension
            _, ext = os.path.splitext(filename)
            ext = ext.lower()

            if not os.path.exists(filename):
                raise IOError(f"Configuration file not found: {filename}")

            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()

            if ext == '.json':
                config = json.loads(content)
            elif ext == '.yaml' or ext == '.yml':
                config = yaml.safe_load(content)
            elif ext == '.ini':
                import configparser
                config = configparser.ConfigParser()
                config.read_string(content)
                config = {section: dict(config.items(section)) for section in config.sections()}
            else:
                raise ValueError(f"Unsupported file format: {ext} for file: {filename}")

            # Apply overrides
            config = _apply_overrides(config, overrides)

            # Resolve environment variables if requested
            if resolve_env and isinstance(config, dict):
                config = _resolve_env_vars(config)

            configs[filename] = config

        except Exception as e:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=f"Failed to load configuration file {filename}: {str(e)}",
                args=(),
                exc_info=e
            )
            errors.append(record)
            logger.error(f"Failed to load configuration file {filename}: {str(e)}")

    return configs, errors

def _apply_overrides(config, overrides):
    """Apply overrides to the config dict"""
    if not isinstance(config, dict) or not isinstance(overrides, dict):
        return config

    for key, value in overrides.items():
        if key in config:
            config[key] = value
        else:
            config[key] = value
    return config

def _resolve_env_vars(obj):
    """Recursively resolve environment variables in a config dict"""
    if isinstance(obj, dict):
        result = {}
        for k, v in obj.items():
            result[k] = _resolve_env_vars(v)
        return result
    elif isinstance(obj, list):
        return [_resolve_env_vars(item) for item in obj]
    elif isinstance(obj, str):
        # Check if it's a single environment variable reference
        if obj.startswith('${') and obj.endswith('}'):
            var_name = obj[2:-1]
            return os.environ.get(var_name, obj)
        # Otherwise, try to find and replace environment variables in the string
        resolved = obj
        import re
        resolved = re.sub(r'\$\{([^}]+)\}', lambda match: os.environ.get(match.group(1), match.group(0)), resolved)
        return resolved
    else:
        return obj
