def determineMetaclass(bases, explicit_mc=None):
    # If explicit_mc is given, return it (it has priority)
    if explicit_mc is not None:
        return explicit_mc

    # Look for __metaclass__ among the bases
    best_mc = None
    for base in bases:
        mc = getattr(base, '__metaclass__', None)
        if mc is not None:
            # Delegate to type(base) to ensure proper metaclass chain resolution?
            # Actually, the correct way: the metaclass of the new class is the
            # most derived metaclass, i.e., the one that is a subclass of all others.
            # But the classic algorithm in Python 2's type.__new__:
            # - If exactly one metaclass, use it.
            # - Otherwise, find the one that is a subclass of all others.
            if best_mc is None:
                best_mc = mc
            else:
                # Check if mc is a subclass of best_mc or vice versa
                if hasattr(mc, '__mro__') and hasattr(best_mc, '__mro__'):
                    # Try to see if mc is subclass of best_mc
                    try:
                        if issubclass(mc, best_mc):
                            # mc is more derived, so mc wins
                            best_mc = mc
                        elif issubclass(best_mc, mc):
                            # best_mc is more derived, keep best_mc
                            pass
                        else:
                            raise TypeError("Error while trying to reduce metaclasses")
                    except TypeError:
                        raise TypeError("Error while trying to reduce metaclasses")
                else:
                    raise TypeError("Error while trying to reduce metaclasses")

    # If no metaclass was found, fall back to type
    if best_mc is None:
        best_mc = type if not hasattr(type, '__mro__') else type

    # Validate that it's a class
    if not isinstance(best_mc, type) and not hasattr(best_mc, '__mro__'):
        # In Python 2, old-style classes don't have __mro__ but are still valid metaclasses
        # Just check it's a class
        if not isinstance(type, type) and not isinstance(best_mc, type):
            pass
        # We accept it as a metaclass candidate
        pass

    return best_mc
