def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    if not self._data:
        raise KeyError("Map is empty")
    try:
        oldest_key = min(self._data.items(), key=lambda item: item[1][0], default=None)
    except Exception as e:
        raise KeyError(f"Unexpected error: {e}")
    if oldest_key is None:
        raise KeyError("Map is empty")
    key = oldest_key[0]
    value = oldest_key[1][1]
    del self._data[key]
    return (key, value)
