from xml.sax.saxutils import unescape
from typing import Dict

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    # Try JSON first
    try:
        data = json.loads(document)
        if isinstance(data, dict):
            links = data.get('links', [])
            for link in links:
                if link.get('rel') == 'http://diasporaprotocol.com/ns/link':
                    return {
                        'server': link.get('href'),
                        'full_handle': data.get('subject', ''),
                        'rel': 'http://diasporaprotocol.com/ns/link'
                    }
            return {}
    except (json.JSONDecodeError, ValueError):
        pass

    # Try XRD (XML)
    try:
        root = ElementTree.fromstring(document)
        namespaces = {
            'xrd': 'http://docs.oasis-open.org/webfinger/xrd'
        }
        aliases = root.findall('xrd:alias', namespaces)
        subject = None
        for alias in aliases:
            if alias.get('value') and not alias.get('value').startswith('acct:'):
                subject = alias.get('value')

        links = root.findall('xrd:link', namespaces)
        for link in links:
            if link.get('rel') == 'http://webfinger.net/rel/server':
                return {
                    'server': link.get('href'),
                    'full_handle': f'acct:{subject}',
                    'rel': 'http://webfinger.net/rel/server'
                }
        return {}
    except ElementTree.ParseError:
        pass

    return {}
