def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    import json
    import re
    import requests

    if not handle:
        return {}

    if '@' not in handle:
        handle = f"urn:xmpp:pid:{handle}"

    # Split into user and domain
    user_part, domain_part = handle.rsplit('@', 1)

    clean_domain = domain_part.lower()

    url = f"https://.well-known/webfinger?resource=acct:{user_part}@{clean_domain}"

    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
        data = response.json()

        # Look for diaspora:person link
        links = data.get("links", [])
        for link in links:
            if link.get("rel") == "http://diaspora.org/ns/relationships/diaspora-person":
                return {
                    "subject": data.get("subject", ""),
                    "alias": data.get("alias", ""),
                    "url": link.get("href", ""),
                    "links": links
                }

        return data

    except requests.RequestException:
        return {}
    except json.JSONDecodeError:
        return {}
