    except yaml.YAMLError as e:
        raise IRValidatorException(f"Failed to parse YAML: {e}")

    if not isinstance(data, dict):
        raise IRValidatorException("spec_content must be a YAML mapping (dictionary)")

    # If there is a 'data' key, use it
    if 'data' in data and isinstance(data['data'], dict):
        spec_data = data['data']
    else:
        spec_data = data

    # Required fields check
    # Example mandatory fields: 'name', 'version'
    # Depending on the spec, there may be more mandatory fields.
    # Here we assume common fields like 'name' and 'version' are required.
    # You can adapt this list based on actual spec requirements.
    mandatory_fields = ['name', 'version']

    for field in mandatory_fields:
        if field not in spec_data:
            raise IRValidatorException(f"Mandatory field '{field}' is missing in spec content")

    return spec_data
