def _get_conditionally_required_args(self, command_name, options_spec, args):
    """
    List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required_args = []
    for option in options_spec:
        # Only process if option has a required_when condition
        if 'required_when' not in option:
            continue

        required_when = option.get('required_when')
        if callable(required_when):
            # If it's a callable, invoke it with args
            try:
                if required_when(args):
                    required_args.append(option.get('name'))
            except Exception:
                # Skip if there's an error in evaluation
                pass
        else:
            # If it's a string or other value, check if args contains that key
            # This is a simplified check - depends on actual spec format
            # Typically, if args is a dict and required_when is a key in args
            # or a list of keys
            try:
                if isinstance(required_when, list):
                    if any(key in args for key in required_when):
                        required_args.append(option.get('name'))
                else:
                    if required_when in args:
                        required_args.append(option.get('name'))
            except Exception:
                pass

    return required_args
