def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        return {}, {}

    if not isinstance(args, (list, tuple)):
        return {}, {}

    control_args = {}
    nested_args = {}
    custom_args = []

    known_control_args = {'verbose', 'dry-run', 'dry_run', 'debug', 'log-level', 'log_level'}
    known_nested_args = {}
    known_custom_args = []

    for arg in args:
        if isinstance(arg, str):
            arg = arg.strip()
            if not arg:
                continue
            if arg.startswith('-'):
                # Could be a control arg
                arg_name = arg.lstrip('-').replace('-', '_')
                if arg_name in known_control_args or arg_name.startswith('verbose') or arg_name.startswith('dry'):
                    control_args[arg_name] = True
                else:
                    # Try to determine if it's a custom arg
                    custom_args.append(arg)
            else:
                # It's a regular argument
                nested_args[arg] = True
        elif isinstance(arg, (list, tuple)) and len(arg) == 2:
            key, value = arg
            if isinstance(key, str):
                key = key.strip()
                if not key:
                    continue
                if key.startswith('-'):
                    arg_name = key.lstrip('-').replace('-', '_')
                    if arg_name in known_control_args or arg_name.startswith('verbose') or arg_name.startswith('dry'):
                        control_args[arg_name] = value
                    else:
                        custom_args.append((key, value))
                else:
                    nested_args[key] = value
        elif isinstance(arg, dict):
            # Merge the dict into nested_args
            for k, v in arg.items():
                nested_args[k] = v

    # Also process custom_args - they might override nested args
    # The docstring says custom args are "to be used instead of the normal nested usage"
    # So we should probably remove nested args that have custom equivalents
    for item in custom_args:
        if isinstance(item, str):
            key = item.lstrip('-').replace('-', '_')
            if key in nested_args:
                del nested_args[key]
        elif isinstance(item, (list, tuple)) and len(item) == 2:
            key, value = item
            if isinstance(key, str):
                key_clean = key.lstrip('-').replace('-', '_')
                if key_clean in nested_args:
                    del nested_args[key_clean]

    return control_args, nested_args
