def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Basic input validation
    if ir_workspace is None:
        raise ValueError("ir_workspace cannot be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin cannot be None")
    if playbook_path is None:
        raise ValueError("playbook_path cannot be None")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dict or None")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dict or None")

    # Try to get ansible config from ir_workspace
    ansible_config = None
    try:
        if hasattr(ir_workspace, 'ansible_config'):
            ansible_config = ir_workspace.ansible_config
    except Exception:
        ansible_config = None

    # Build the command
    import shlex
    import os

    # Determine the ansible-playbook path
    if ansible_config and hasattr(ansible_config, 'ansible_playbook'):
        command = ansible_config.ansible_playbook
    else:
        command = "ansible-playbook"

    # Build args list
    args = [command]

    # Add verbosity
    if verbose is not None:
        verbose_str = str(verbose).lower()
        if verbose_str in ['1', '2', '3', '4', '5']:
            args.append("-" + verbose_str)
        elif isinstance(verbose, int) and verbose > 0:
            args.append("-" + "v" * verbose)

    # Add extra_vars
    if extra_vars:
        from json import dumps
        extra_vars_str = dumps(extra_vars)
        args.append("-e")
        args.append(extra_vars_str)

    # Add ansible_args
    if ansible_args:
        for key, value in ansible_args.items():
            arg_name = "-" + key.replace("_", "-")
            if value is not None:
                if isinstance(value, bool):
                    if value:
                        args.append(arg_name)
                elif isinstance(value, (list, tuple)):
                    for val in value:
                        args.append(arg_name)
                        if not isinstance(val, bool):
                            args.append(str(val))
                else:
                    args.append(arg_name)
                    args.append(str(value))

    # Add playbook_path
    args.append(playbook_path)

    # Execute the command
    import subprocess

    try:
        result = subprocess.run(args, capture_output=True, text=True, timeout=300)
        return result
    except subprocess.TimeoutExpired:
        raise Exception("ansible-playbook command timed out")
    except FileNotFoundError:
        raise Exception(f"Command not found: {command}")
    except Exception as e:
        raise Exception(f"Failed to execute ansible-playbook: {str(e)}")
