    import json
    import yaml

    def flatten(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten(v, new_key, sep=sep).items())
            elif isinstance(v, list):
                # For lists, keep as single value (common in plugin specs for simple lists)
                items.append((new_key, v))
            else:
                items.append((new_key, v))
        return dict(items)

    if not os.path.exists(plugin_dir):
        raise ValueError(f"Plugin directory {plugin_dir} does not exist")

    spec_file_candidates = [
        os.path.join(plugin_dir, 'plugin_spec.json'),
        os.path.join(plugin_dir, 'plugin.json'),
        os.path.join(plugin_dir, 'plugin.yaml'),
        os.path.join(plugin_dir, 'plugin.yml'),
        os.path.join(plugin_dir, 'spec.yaml'),
        os.path.join(plugin_dir, 'spec.yml')
    ]

    spec_file = None
    for candidate in spec_file_candidates:
        if os.path.isfile(candidate):
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    spec_data = {}
    try:
        if spec_file.endswith(('.json',)):
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec_data = json.load(f)
        elif spec_file.endswith(('.yaml', '.yml')):
            with open(spec_file, 'r', encoding='utf-8') as f:
                spec_data = yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported spec file format: {spec_file}")
    except (json.JSONDecodeError, yaml.YAMLError) as e:
        raise ValueError(f"Failed to parse plugin spec file {spec_file}: {e}")

    if not isinstance(spec_data, dict):
        raise ValueError(f"Plugin spec file {spec_file} does not contain a dictionary at the top level")

    return flatten(spec_data)
